import React from "react";
import { palette } from "../theme/palette";
import { Chhatri, Dome, archPath, cuspedArchPath } from "./WeddingDaySets";

/*
 * Vidai set: a lantern-lit palace gateway (darwaza) at dusk. The arch opening glows warm; the
 * couple stands in it. Scene space; `base` is the threshold line.
 */

export const GATE = { x0: 110, x1: 830, arch: { x: 270, w: 400, spring: 1080, apex: 840 }, base: 1486 };

/** Warm glow seen through the gate (the lit courtyard beyond). Draw before the gate. */
export const GateGlow: React.FC<{ id: string; intensity?: number }> = ({ id, intensity = 1 }) => {
  const a = GATE.arch;
  return (
    <g>
      <defs>
        <radialGradient id={id} cx="0.5" cy="0.75" r="0.7">
          <stop offset="0" stopColor="#FFE2A6" />
          <stop offset="0.5" stopColor="#F2B06A" />
          <stop offset="1" stopColor="#B5605A" />
        </radialGradient>
      </defs>
      <path d={archPath(a.x - 10, a.w + 20, a.spring, a.apex - 20, GATE.base + 4)} fill={`url(#${id})`} opacity={intensity} />
      {/* courtyard pillars far inside, soft */}
      {[0.22, 0.5, 0.78].map((k) => (
        <rect key={k} x={a.x + a.w * k - 14} y={a.spring - 20} width={28} height={GATE.base - a.spring + 20} fill="#D98C62" opacity={0.35} />
      ))}
    </g>
  );
};

/** The gateway: walls, twin towers with chhatris, a cusped arch with a carved frame. */
export const PalaceGate: React.FC<{ wall: string; shade: string; trim: string; lit: string }> = ({ wall, shade, trim, lit }) => {
  const { x0, x1, arch: a, base } = GATE;
  const top = 700;
  const hole = cuspedArchPath(a.x, a.w, a.spring, a.apex, base + 10, 7);
  const frame = archPath(a.x - 40, a.w + 80, a.spring, a.apex - 60, base + 10);
  const win = (x: number, y: number, w: number) => (
    <g>
      <path d={archPath(x - w / 2 - 5, w + 10, y + w * 0.5, y - 6, y + w * 1.6)} fill={shade} />
      <path d={archPath(x - w / 2, w, y + w * 0.5, y, y + w * 1.6)} fill={lit} />
      <rect x={x - w / 2} y={y + w * 1.1} width={w} height={w * 0.5} fill="url(#jali)" opacity={0.5} />
    </g>
  );
  return (
    <g>
      {/* main facade with the opening cut out */}
      <path d={`M${x0} ${base + 10} L${x0} ${top} L${x1} ${top} L${x1} ${base + 10} Z ${hole}`} fill={wall} fillRule="evenodd" />
      {/* parapet */}
      {new Array(Math.floor((x1 - x0) / 24)).fill(0).map((_, i) => (
        <path key={i} d={`M${x0 + i * 24 + 4} ${top} L${x0 + i * 24 + 4} ${top - 12} Q${x0 + i * 24 + 12} ${top - 22} ${x0 + i * 24 + 20} ${top - 12} L${x0 + i * 24 + 20} ${top} Z`} fill={wall} />
      ))}
      <rect x={x0} y={top} width={x1 - x0} height={5} fill={trim} opacity={0.8} />
      {/* carved frame and spandrels */}
      <path d={`${frame} ${hole}`} fill={shade} fillRule="evenodd" opacity={0.55} />
      <path d={frame} fill="none" stroke={trim} strokeWidth={2.5} />
      <path d={hole} fill="none" stroke={trim} strokeWidth={3} />
      <path d={archPath(a.x - 60, a.w + 120, a.spring, a.apex - 90, base + 10)} fill="none" stroke={trim} strokeWidth={1} opacity={0.6} strokeDasharray="2 6" />
      {[a.x - 90, a.x + a.w + 90].map((x) => (
        <g key={x} transform={`translate(${x} ${a.apex - 20})`}>
          {new Array(8).fill(0).map((_, i) => (
            <path key={i} d="M0 0 C7 -9 7 -22 0 -30 C-7 -22 -7 -9 0 0 Z" transform={`rotate(${i * 45})`} fill="none" stroke={trim} strokeWidth={1.3} />
          ))}
          <circle r={6} fill={trim} />
        </g>
      ))}
      {/* side windows */}
      {win((x0 + a.x) / 2 + 20, 900, 48)}
      {win((a.x + a.w + x1) / 2 - 20, 900, 48)}
      {win((x0 + a.x) / 2 + 20, 1180, 56)}
      {win((a.x + a.w + x1) / 2 - 20, 1180, 56)}
      <rect x={x0} y={1120} width={x1 - x0} height={4} fill={trim} opacity={0.6} />
      {/* twin towers */}
      {[x0 - 10, x1 + 10].map((x, i) => (
        <g key={x}>
          <rect x={x - 60} y={560} width={120} height={base + 10 - 560} fill={wall} />
          <rect x={i ? x - 60 : x + 26} y={560} width={34} height={base + 10 - 560} fill={shade} opacity={0.4} />
          <rect x={x - 68} y={552} width={136} height={12} fill={shade} />
          <rect x={x - 68} y={552} width={136} height={3} fill={trim} />
          {win(x, 640, 40)}
          {win(x, 1000, 44)}
          <rect x={x - 60} y={860} width={120} height={4} fill={trim} opacity={0.6} />
          <Chhatri cx={x} by={552} w={96} fill={wall} shade={shade} glow={lit} />
        </g>
      ))}
      {/* crown over the arch */}
      <rect x={a.x + a.w / 2 - 110} y={top - 60} width={220} height={60} fill={wall} />
      <rect x={a.x + a.w / 2 - 118} y={top - 66} width={236} height={10} fill={shade} />
      <Dome cx={a.x + a.w / 2} by={top - 66} w={150} h={110} fill={wall} shade={shade} finial={trim} line={trim} />
      {/* threshold steps */}
      <rect x={a.x - 60} y={base + 10} width={a.w + 120} height={16} fill={shade} />
      <rect x={a.x - 90} y={base + 26} width={a.w + 180} height={16} fill={wall} />
      <rect x={a.x - 90} y={base + 26} width={a.w + 180} height={2} fill={trim} opacity={0.7} />
      {/* dusk shading across the lower wall */}
      <rect x={x0 - 80} y={base - 300} width={x1 - x0 + 160} height={336} fill={palette.dusk} opacity={0.12} />
    </g>
  );
};
